INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Überwachung von Serverdiensten notwendig, um deren Verfügbarkeit sicherzustellen?', 2, '[{"text": "Ja", "correct": true, "because": "Überwachung erkennt Ausfälle frühzeitig"}, {"text": "Nein", "correct": false, "because": "Verfügbarkeit erfordert Überwachung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Überwachung von Serverdiensten ohne spezielle Software erfolgen?', 2, '[{"text": "Nein", "correct": true, "because": "Tools sind für effektive Überwachung nötig"}, {"text": "Ja", "correct": false, "because": "Manuelle Überwachung ist ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Wird SNMP häufig zur Überwachung von Serverdiensten eingesetzt?', 2, '[{"text": "Ja", "correct": true, "because": "Simple Network Management Protocol ist Standard"}, {"text": "Nein", "correct": false, "because": "SNMP ist weit verbreitet"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Leistungsdaten von Serverdiensten protokolliert werden?', 2, '[{"text": "Ja", "correct": true, "because": "Protokollierung hilft bei der Analyse"}, {"text": "Nein", "correct": false, "because": "Protokolle sind Best Practice"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Überwachung von Serverdiensten auch Sicherheitsprobleme erkennen?', 2, '[{"text": "Ja", "correct": true, "because": "Anomalien können Sicherheitsvorfälle anzeigen"}, {"text": "Nein", "correct": false, "because": "Sicherheit ist oft Teil der Überwachung"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll wird typischerweise verwendet, um Serverdienste zu überwachen?', 2, '[{"text": "SNMP", "correct": true, "because": "Standard für Dienstüberwachung"}, {"text": "HTTP", "correct": false, "because": "Für Webzugriff, nicht Überwachung"}, {"text": "DHCP", "correct": false, "because": "Für IP-Vergabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool ist bekannt für die Überwachung von Serverdiensten?', 3, '[{"text": "Nagios", "correct": true, "because": "Nagios überwacht Dienste und Verfügbarkeit"}, {"text": "Wireshark", "correct": false, "because": "Für Paketanalyse, nicht Dienste"}, {"text": "Excel", "correct": false, "because": "Kein Überwachungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metrik wird oft überwacht, um die Leistung eines Serverdienstes zu bewerten?', 2, '[{"text": "CPU-Auslastung", "correct": true, "because": "Zeigt Dienstleistungskapazität"}, {"text": "Bildschirmgröße", "correct": false, "because": "Irrelevant für Server"}, {"text": "Bandbreitenverbrauch", "correct": false, "because": "Netzwerkbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Funktion hat ein Überwachungssystem bei Serverdiensten?', 2, '[{"text": "Alarmierung bei Ausfällen", "correct": true, "because": "Benachrichtigt bei Problemen"}, {"text": "Datenverschlüsselung", "correct": false, "because": "Nicht Aufgabe der Überwachung"}, {"text": "IP-Zuweisung", "correct": false, "because": "Das macht DHCP"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Zeitraum ist für die Überwachung von Serverdiensten besonders wichtig?', 2, '[{"text": "Echtzeit", "correct": true, "because": "Echtzeitdaten zeigen aktuellen Status"}, {"text": "Wöchentlich", "correct": false, "because": "Zu selten für Dienste"}, {"text": "Einmalig", "correct": false, "because": "Keine kontinuierliche Überwachung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden bei der Überwachung von Serverdiensten typischerweise geprüft?', 4, '[{"text": "Dienstverfügbarkeit", "correct": true, "because": "Prüft, ob Dienste laufen"}, {"text": "CPU-Auslastung", "correct": true, "because": "Beeinflusst Leistung"}, {"text": "Speicherverbrauch", "correct": true, "because": "Wichtig für Stabilität"}, {"text": "Bildschirmauflösung", "correct": false, "because": "Nicht relevant für Server"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Protokolle können für die Überwachung von Serverdiensten genutzt werden?', 3, '[{"text": "SNMP", "correct": true, "because": "Standard für Dienstüberwachung"}, {"text": "ICMP", "correct": true, "because": "Prüft Erreichbarkeit"}, {"text": "Syslog", "correct": true, "because": "Für Protokollmeldungen"}, {"text": "FTP", "correct": false, "because": "Für Dateiübertragung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Tools sind für die Überwachung von Serverdiensten geeignet?', 4, '[{"text": "Nagios", "correct": true, "because": "Überwacht Dienste"}, {"text": "Zabbix", "correct": true, "because": "Umfassende Serverüberwachung"}, {"text": "Prometheus", "correct": true, "because": "Für Metriken und Alarme"}, {"text": "Paint", "correct": false, "because": "Kein Überwachungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Überwachung von Serverdiensten?', 3, '[{"text": "Früherkennung von Ausfällen", "correct": true, "because": "Verhindert Downtime"}, {"text": "Leistungsoptimierung", "correct": true, "because": "Identifiziert Ressourcenengpässe"}, {"text": "Hohe Kosten", "correct": false, "because": "Kein Vorteil"}, {"text": "Sicherheitsüberprüfung", "correct": true, "because": "Erkennt Anomalien"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ereignisse sollten bei der Überwachung von Serverdiensten protokolliert werden?', 3, '[{"text": "Dienstausfälle", "correct": true, "because": "Wichtig für Analyse"}, {"text": "Ressourcenüberlastung", "correct": true, "because": "Zeigt Leistungsprobleme"}, {"text": "Sicherheitsvorfälle", "correct": true, "because": "Erkennt Angriffe"}, {"text": "Benutzeranmeldungen", "correct": false, "because": "Client-spezifisch"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die Überwachung von Serverdiensten erkennt Ausfälle. b) SNMP ist für die Überwachung ungeeignet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle ja, SNMP geeignet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Nagios kann Serverdienste überwachen. b) Protokollierung ist bei der Überwachung unnötig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Nagios ja, Protokollierung wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) ICMP kann die Verfügbarkeit von Diensten prüfen. b) CPU-Auslastung ist irrelevant für die Überwachung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "ICMP ja, CPU relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Überwachung hilft bei der Leistungsoptimierung. b) Echtzeitdaten sind für die Überwachung unwichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Optimierung ja, Echtzeit wichtig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Überwachung kann Sicherheitsprobleme erkennen. b) Zabbix ist ein geeignetes Überwachungstool.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Sicherheit ja, Zabbix geeignet"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');

